import React, { useMemo, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, OrbitControls } from '@react-three/drei';

function TorusKnot() {
  const ref = useRef();
  useFrame((_, delta) => {
    if (!ref.current) return;
    ref.current.rotation.x += delta * 0.15;
    ref.current.rotation.y += delta * 0.22;
  });

  return (
    <Float speed={1.4} rotationIntensity={0.5} floatIntensity={1.1}>
      <mesh ref={ref} position={[1.2, 0.2, 0]} scale={0.95}>
        <torusKnotGeometry args={[1, 0.28, 160, 24]} />
        <MeshDistortMaterial
          color="#14b8a6"
          attach="material"
          distort={0.28}
          speed={1.6}
          roughness={0.25}
          metalness={0.45}
          transparent
          opacity={0.85}
        />
      </mesh>
    </Float>
  );
}

function OrbitNodes() {
  const group = useRef();
  const nodes = useMemo(
    () =>
      Array.from({ length: 14 }, (_, i) => {
        const angle = (i / 14) * Math.PI * 2;
        const radius = 2.4 + (i % 3) * 0.25;
        return {
          position: [Math.cos(angle) * radius, Math.sin(angle * 1.4) * 0.55, Math.sin(angle) * radius * 0.35],
          scale: 0.06 + (i % 4) * 0.02,
          color: i % 2 === 0 ? '#c4a35a' : '#0f766e',
        };
      }),
    []
  );

  useFrame((_, delta) => {
    if (group.current) group.current.rotation.y += delta * 0.12;
  });

  return (
    <group ref={group} position={[-0.6, 0.1, -0.4]}>
      {nodes.map((node, i) => (
        <mesh key={i} position={node.position} scale={node.scale}>
          <icosahedronGeometry args={[1, 0]} />
          <meshStandardMaterial color={node.color} metalness={0.5} roughness={0.35} />
        </mesh>
      ))}
    </group>
  );
}

function BlueprintGrid() {
  return (
    <mesh rotation={[-Math.PI / 2.4, 0, 0]} position={[0, -1.6, 0]}>
      <planeGeometry args={[18, 18, 24, 24]} />
      <meshBasicMaterial color="#94a3b8" wireframe transparent opacity={0.18} />
    </mesh>
  );
}

const HeroScene = () => {
  return (
    <Canvas
      dpr={[1, 1.5]}
      camera={{ position: [0, 0.4, 6.2], fov: 42 }}
      gl={{ antialias: true, alpha: true }}
      style={{ background: 'transparent' }}
    >
      <ambientLight intensity={0.7} />
      <directionalLight position={[4, 5, 2]} intensity={1.1} color="#e8eef8" />
      <pointLight position={[-3, 1, 2]} intensity={0.8} color="#14b8a6" />
      <BlueprintGrid />
      <TorusKnot />
      <OrbitNodes />
      <OrbitControls enableZoom={false} enablePan={false} autoRotate autoRotateSpeed={0.35} />
    </Canvas>
  );
};

export default HeroScene;
